(place:Place {id: row.place_id}) SET place.name = row.place_name, place.country_code = 'KR', place.place_type = 'gbif_admin_area' MERGE (observation:Observation {id: row.id}) SET observation.occurrence_id = row.occurrence_id, observation.event_id = row.event_id, observation.scientific_name_raw = row.scientific_name_raw, observation.observed_at = row.observed_at, observation.event_date_precision = row.event_date_precision, observation.count = row.count, observation.basis = row.basis, observation.lat = row.lat, observation.lon = row.lon, observation.coordinate_uncertainty_m = row.coordinate_uncertainty_m, observation.geodetic_datum = row.geodetic_datum, observation.sensitivity = row.sensitivity, observation.source_record_key = row.source_record_key, observation.ingestion_run_id = $run_id, observation.dataset_id = $dataset_id, observation.source_dataset_id = row.dataset_id, observation.source_record_id = row.source_record_key, observation.source_uri = row.raw_uri, observation.source_retrieved_at = row.retrieved_at, observation.source_updated_at = row.source_updated_at, observation.license_uri = row.license_uri, observation.policy_status = 'allowed' MERGE (observation)-[:IDENTIFIED_AS]->(taxon) MERGE (observation)-[:WITHIN]->(place) MERGE (evidence:EvidenceUnit {id: 'gbif-evidence:' + row.external_id}) SET evidence.evidence_type = 'observation', evidence.locator = row.raw_uri, evidence.accessed_at = row.retrieved_at, evidence.dataset_id = $dataset_id, evidence.source_record_id = row.source_record_key, evidence.policy_status = 'allowed' MERGE (observation)-[:SUPPORTED_BY]->(evidence) RETURN count(*) AS loaded_observations } CALL { UNWIND $media AS row MATCH (observation:Observation {id: row.observation_id}) MERGE (asset:MediaAsset {id: row.id}) SET asset.media_type = row.media_type, asset.format = row.format, asset.landing_uri = row.landing_uri, asset.asset_uri = row.asset_uri, asset.creator = row.creator, asset.publisher = row.publisher, asset.attribution = row.attribution, asset.license_uri = row.license_uri, asset.redistribution_allowed = true, asset.retrieved_at = row.retrieved_at, asset.dataset_id = $dataset_id, asset.policy_status = 'allowed' MERGE (observation)-[:HAS_MEDIA]->(asset) RETURN count(*) AS loaded_media } RETURN loaded_taxa, loaded_taxon_links, loaded_observations, loaded_media, 'domain_verified' AS status".replace(/\$([A-Za-z_][A-Za-z0-9_]*)/g, (_, key) => values[key]); })() }}

